CHANGELOG = '## [0.239.0] - a roof hatch stands over its ladder\'s cut: the hole, the curb and the lid are one rectangle\n\n**The factory\'s roadmap 170.** The walker\'s look review, 2026-10-19, on the roof hatch: "the hole of the ladder\nopening doesn\'t match the lid...they should match". Read off the built slots: a roof ladder cuts its own hole,\n`ladder_geom.through_hole` -- the body\'s envelope, 1.1 x 1.3 m, set 0.45 m toward the side the climber stands on --\nand `_vertical_links` cut the hatch\'s 1.5 m square centred on the ladder\'s face. The roof took both cuts, so its\nopening ran 0.35 m past the square on the climber\'s side, and 0.27 m past the curb that 0.224.0 sized to the\nsquare. All 46 roof hatch links in the library have a ladder, and every one ran out by the same 0.35 m. The 20\nhatches below the roof have no ladder, and nothing changes for them.\n\n### Fixed\n- `roof_hatch.opening(spec, link)`: the hole a roof hatch covers. It is the link\'s square, centred on the cuts of\n  the ladders at the link that reach its storey, where it holds them -- the 1.5 m square holds the ladder\'s 1.1 x\n  1.3. Where the square cannot hold them it is the box round both. With no such ladder it is the square where the\n  link stands, as before.\n- `_vertical_links` cuts a roof hatch\'s slab hole at `opening`, and files its drop link\'s points and its `hole`\n  there. `roof_hatches` stands the slot over it: the curb\'s world footprint is the opening plus `CURB` a side, and a\n  quarter-turned slot carries those sides swapped as its own (w, d), as `hole_causes._local` does. Every roof hatch\n  in the library today is square, so no Zoo module changes. The hatch moves 0.45 m toward its climber, and its\n  `HATCH_` marker and its ids stay keyed on the link.\n\n### Tests\n- `test_roof_hatch.py`:\n  - the first test\'s slot now stands at the ladder\'s cut, (13.0, -9.45), where it stood at the link;\n  - the ladder\'s cut lies inside the opening, and the opening is the curb\'s inside, for a ladder facing each of N, E,\n    S and W;\n  - with no ladder, the hatch stands on its link;\n  - a square too small for the cut grows round both, and a quarter turn swaps the slot\'s sides;\n  - in the built library, every roof hatch\'s curb holds every hole the roof is cut with under it. 39 built hatches;\n    on 0.238.0\'s build every one fails, with the ladder\'s cut out past the curb.\n- 8 of the file\'s 12 fail on 0.238.0.\n\n'
OLD_VERSION, NEW_VERSION = 'Deli Counter 0.238.0', 'Deli Counter 0.239.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: deli_counter/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: deli_counter/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: deli_counter/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: deli_counter/%s exists already; nothing written" % name)
    v = REPO / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = REPO / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.split()[-1].encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("%s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in deli_counter/: build.py --all, "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
